// On-device WalletConnect log (opt-in: open the app with ?wcdebug=1; ?wcdebug=0
// turns it off). A phone has no console, and a mobile wallet handoff leaves
// the tab, so this keeps a persistent ring buffer of what the app sent to the
// wallet, what came back, and when the tab was hidden or shown, plus a small
// panel to read and copy it. No addresses: accounts are reduced to their chain.

const STORE_KEY = 'degenerus:wcdebug:log';
const MAX_ENTRIES = 120;
const instrumented = new WeakSet();
let entries = [];
let panelList = null;

function load() {
  try { entries = JSON.parse(localStorage.getItem(STORE_KEY) || '[]'); } catch (_e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
}

function save() {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(entries)); } catch (_e) { /* quota/private */ }
}

function stamp() {
  const d = new Date();
  return d.toTimeString().slice(0, 8) + '.' + String(d.getMilliseconds()).padStart(3, '0');
}

function text(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, (_k, v) => (typeof v === 'bigint' ? v.toString() : v));
  } catch (_e) { return String(value); }
}

function errorText(error) {
  if (!error) return '';
  const code = error.code ?? error.info?.error?.code ?? error.error?.code;
  const message = error.info?.error?.message || error.error?.message || error.message || String(error);
  return `${code != null ? `[${code}] ` : ''}${String(message).slice(0, 220)}`;
}

export function log(event, detail = '') {
  entries.push(`${stamp()} ${event} ${text(detail)}`.trim());
  if (entries.length > MAX_ENTRIES) entries = entries.slice(-MAX_ENTRIES);
  save();
  render();
}

function sessionSummary(provider) {
  const session = provider?.session;
  if (!session) return 'none';
  const chains = new Set();
  const methods = new Set();
  for (const ns of Object.values(session.namespaces || {})) {
    for (const account of ns?.accounts || []) chains.add(String(account).split(':').slice(0, 2).join(':'));
    for (const method of ns?.methods || []) methods.add(method);
  }
  return {
    topic: String(session.topic || '').slice(0, 10),
    peer: session.peer?.metadata?.name || '',
    accountChains: [...chains],
    send: methods.has('eth_sendTransaction'),
    switch: methods.has('wallet_switchEthereumChain'),
    expiry: session.expiry ? new Date(session.expiry * 1000).toISOString().slice(0, 16) : '',
    providerChain: provider?.chainId,
    relay: provider?.signer?.client?.core?.relayer?.connected,
  };
}

function wrapRequest(target, name, describe) {
  const original = target?.request;
  if (typeof original !== 'function') return;
  target.request = async function loggedRequest(args, ...rest) {
    const label = describe(args);
    const started = Date.now();
    log(`${name}→`, label);
    try {
      const result = await original.call(this, args, ...rest);
      log(`${name}✓`, `${label.method || label} ${Date.now() - started}ms ${text(result).slice(0, 80)}`);
      return result;
    } catch (error) {
      log(`${name}✗`, `${label.method || label} ${Date.now() - started}ms ${errorText(error)}`);
      throw error;
    }
  };
}

export function instrumentWalletConnect(provider) {
  if (!provider || instrumented.has(provider)) return;
  instrumented.add(provider);
  log('wc:init', sessionSummary(provider));
  // Requests the app makes through the EIP-1193 provider.
  wrapRequest(provider, 'eip1193', (args) => ({
    method: args?.method,
    chainId: args?.params?.[0]?.chainId,
  }));
  // Requests that reach the wallet over the relay (SignClient).
  const client = provider.signer?.client;
  wrapRequest(client, 'relay', (args) => ({
    method: args?.request?.method,
    chainId: args?.chainId,
    topic: String(args?.topic || '').slice(0, 10),
  }));
  for (const event of ['session_request_sent', 'session_update', 'session_delete', 'session_expire', 'session_event']) {
    try {
      client?.on?.(event, (payload) => log(`client:${event}`, {
        id: payload?.id,
        topic: String(payload?.topic || '').slice(0, 10),
        method: payload?.request?.method,
        chainId: payload?.chainId,
        event: payload?.params?.event?.name,
      }));
    } catch (_e) { /* nonstandard client */ }
  }
  for (const event of ['connect', 'disconnect', 'chainChanged', 'session_update', 'session_delete']) {
    try { provider.on?.(event, (payload) => log(`provider:${event}`, event === 'chainChanged' ? payload : '')); } catch (_e) { /* nonstandard */ }
  }
  try {
    provider.signer?.client?.core?.relayer?.on?.('relayer_connect', () => log('relay:connect'));
    provider.signer?.client?.core?.relayer?.on?.('relayer_disconnect', () => log('relay:disconnect'));
  } catch (_e) { /* nonstandard */ }
  globalThis.__wcDebugSession = () => log('wc:session', sessionSummary(provider));
}

function render() {
  if (!panelList) return;
  panelList.textContent = entries.slice().reverse().join('\n');
}

function mountPanel() {
  if (typeof document === 'undefined' || document.querySelector('.wc-debug')) return;
  const root = document.createElement('div');
  root.className = 'wc-debug';
  root.style.cssText = 'position:fixed;z-index:2147483600;left:6px;top:calc(env(safe-area-inset-top) + 6px);'
    + 'font:11px/1.35 ui-monospace,Menlo,monospace;color:#e7f4ff';
  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.textContent = 'WC LOG';
  toggle.style.cssText = 'padding:4px 8px;border:1px solid #6fb7ff;border-radius:6px;background:#0d1b2bcc;color:inherit;font:inherit';
  const box = document.createElement('div');
  box.hidden = true;
  box.style.cssText = 'margin-top:4px;width:min(94vw,560px);max-height:62dvh;display:flex;flex-direction:column;gap:4px;'
    + 'padding:6px;border:1px solid #6fb7ff;border-radius:8px;background:#060b12f2';
  const actions = document.createElement('div');
  actions.style.cssText = 'display:flex;gap:6px';
  const button = (label, onClick) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.style.cssText = 'padding:3px 8px;border:1px solid #6fb7ff88;border-radius:5px;background:#12253a;color:inherit;font:inherit';
    b.addEventListener('click', onClick);
    actions.appendChild(b);
    return b;
  };
  const copy = button('COPY', async () => {
    try {
      await navigator.clipboard.writeText(entries.join('\n'));
      copy.textContent = 'COPIED';
    } catch (_e) { copy.textContent = 'COPY FAILED'; }
    setTimeout(() => { copy.textContent = 'COPY'; }, 1500);
  });
  button('SESSION', () => globalThis.__wcDebugSession?.() ?? log('wc:session', 'no WalletConnect provider yet'));
  button('CLEAR', () => { entries = []; save(); render(); });
  panelList = document.createElement('pre');
  panelList.style.cssText = 'margin:0;overflow:auto;white-space:pre-wrap;word-break:break-all;min-height:4rem';
  box.append(actions, panelList);
  toggle.addEventListener('click', () => { box.hidden = !box.hidden; });
  root.append(toggle, box);
  document.body.appendChild(root);
  render();
}

load();
log('page', `${location.pathname} visible=${document.visibilityState}`);
document.addEventListener('visibilitychange', () => log('tab', document.visibilityState));
window.addEventListener('pagehide', (event) => log('pagehide', event.persisted ? 'bfcache' : ''));
window.addEventListener('pageshow', (event) => { if (event.persisted) log('pageshow', 'bfcache'); });
globalThis.__wcDebug = log;
if (document.body) mountPanel();
else document.addEventListener('DOMContentLoaded', mountPanel, { once: true });
